package sfc

import (
	"bytes"

	"github.com/ethereum/go-ethereum/common/hexutil"
	"github.com/ethereum/go-ethereum/log"
)

// GetPatch8ContractBin returns the Cycle-163 self-service-reactivation SFC
// bytecode re-flashed by the SfcV2Patch8 upgrade. It is distinct from the
// historical Patch4/Patch5/Patch6/Patch7 accessors so each sealed testnet
// re-flash remains reproducible, while fresh SfcV2 activations consume this
// bytecode through GetLatestContractBin().
//
// Cycle-163 source: VinuChain/vinuchain-lists contracts/vinuchain/SFC.sol.
// Compile it with the pinned toolchain, byte-for-byte:
//
//	solc 0.5.17+commit.d19bba13 --optimize --optimize-runs=10000 \
//	     --evm-version=istanbul
//
// Delta from Cycle-162 reward-cursor bytecode (SfcV2Patch7): full self-service
// reactivateValidator. reactivateValidator drops onlyOwner for a
// nonReentrant owner-OR-self gate (the validator's own immutable auth key may
// reactivate ONLY from a pure-OFFLINE status, after an anti-flap cooldown of
// offlinePenaltyThresholdTime; owner retains the looser power for lost-key
// recovery). Doublesign/cheater validators (CHEATER_MASK) stay permanently
// un-reactivatable for ALL callers. To avoid freezing delegators across the
// offline gap, two appended mappings (reactivationHealFloor,
// reactivationHealFrom) capture the pre-gap reward rate R at deactivation and
// let _getEffectiveRewardRate carry R forward across the gap epochs while
// _sealEpoch_rewards reseeds the re-entry epoch from R, so the monotonic reward
// index never inverts and no owner correction is required.
//
// Validity of the compiled asset is enforced at opera binary startup via
// EnforcePatch8StartupCheck.
func GetPatch8ContractBin() []byte {
	return patch8ContractBin
}

// EnforcePatch8StartupCheck validates the compiled-in Patch8 bytecode at
// binary startup. A build whose Patch8 bytes are placeholder, all zero, too
// short, or byte-identical to Patch6/Patch7 refuses to start rather than
// reaching the on-chain re-flash block with an invalid asset.
func EnforcePatch8StartupCheck() {
	if err := validatePatch8Bytecode(patch8ContractBin); err != nil {
		log.Crit("SfcV2Patch8 bytecode asset is invalid - the binary must not start with this build. Recompile SFC from vinuchain-lists and replace sfc_patch8_bytecode.go", "err", err)
	}
}

var patch8DeadbeefSentinel = []byte{0xde, 0xad, 0xbe, 0xef}

// patch8ContractBin is the Cycle-163 self-service-reactivation SFC runtime bytecode.
//
// Compiled from VinuChain/vinuchain-lists contracts/vinuchain/SFC.sol with the pinned
// toolchain, byte-for-byte reproducible (SFC contract, runtime part):
//
//	solc 0.5.17+commit.d19bba13 --optimize --optimize-runs=10000 --evm-version=istanbul \
//	     --bin-runtime contracts/vinuchain/SFC.sol
//
// Provenance — recompute and confirm byte-identical in the official release build (as
// every prior SfcV2Patch cycle was) and add a Cycle-163 row to deployment-log.md SFC
// Patch History BEFORE flashing to any live network:
//
//	Size:             48147 bytes
//	raw-bytes sha256: 0e6fd265ec21b15998c6d582e5b8cb9467e7ce954242bc346bc7b103a78ee164
var patch8ContractBin = hexutil.MustDecode("")

// minRealPatch8BytecodeLen is a lower bound on a legitimate compiled SFC. A real
// Cycle-163 SFC is ~47 KB; 10000 bytes rejects sentinel-sized placeholders while
// leaving head-room for plausible future compiles.
const minRealPatch8BytecodeLen = 10000

// validatePatch8Bytecode returns a non-nil error if the argument is not a
// plausible real compiled SFC, so neither EnforcePatch8StartupCheck nor any
// future release can ship the sentinel bytes in place of a real compile.
func validatePatch8Bytecode(code []byte) error {
	if len(code) == 0 {
		return errPatch8Empty
	}
	if len(code) < minRealPatch8BytecodeLen {
		return errPatch8TooShort
	}
	if len(code) >= len(patch8DeadbeefSentinel) && bytes.Equal(code[:len(patch8DeadbeefSentinel)], patch8DeadbeefSentinel) {
		return errPatch8Sentinel
	}
	allZero := true
	for _, b := range code {
		if b != 0 {
			allZero = false
			break
		}
	}
	if allZero {
		return errPatch8AllZero
	}
	if bytes.Equal(code, GetPatch6ContractBin()) {
		return errPatch8EqualsPatch6
	}
	if bytes.Equal(code, GetPatch7ContractBin()) {
		return errPatch8EqualsPatch7
	}
	return nil
}

type patch8Error string

func (e patch8Error) Error() string { return string(e) }

const (
	errPatch8Empty        patch8Error = "patch8 bytecode is empty"
	errPatch8TooShort     patch8Error = "patch8 bytecode shorter than minimum SFC size - placeholder not replaced"
	errPatch8Sentinel     patch8Error = "patch8 bytecode begins with deadbeef sentinel - placeholder not replaced"
	errPatch8AllZero      patch8Error = "patch8 bytecode is all zeros"
	errPatch8EqualsPatch6 patch8Error = "SfcV2Patch8 bytecode is byte-identical to Patch6 (Cycle-162 orphan-stake) - the Patch8 re-flash would no-op on chain and the reactivation fix would not deploy"
	errPatch8EqualsPatch7 patch8Error = "SfcV2Patch8 bytecode is byte-identical to Patch7 (Cycle-162 reward-cursor) - the Patch8 re-flash would no-op on chain and the reactivation fix would not deploy"
)
